head.script:
scwin.autoComplete1_onviewchange = function(info) {
    if (info.newValue == "G") {
        autoComplete1.setValue(info.oldValue);
    }
};
scwin.trigger1_onclick = function(e) {
    WebSquare.wUnit.getObjById('autoComplete1_label').click();
    WebSquare.wUnit.getObjById('autoComplete1_input').focus();
    autoComplete1.inputKeyDown({
        keyCode: 85
    }, false);
    WebSquare.wUnit.getObjById('autoComplete1_input').value = "U";
    //console.log(autoComplete1.viewArr);
};
scwin.unitTest = function() {
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "20");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('autoComplete1_label').textContent == 'UY'", "true");
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.trigger2_onclick = function(e) {
    autoComplete1.inputKeyDown({
        keyCode: 13
    }, false);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsonData = [{
            "value": "G",
            "label": "G"
        },
        {
            "value": "Y",
            "label": "UY"
        },
        {
            "value": "Y2",
            "label": "UY2"
        },
        {
            "value": "N",
            "label": "N"
        }
    ];
    dl_select.setJSON(jsonData);
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
